/* scan_wide.c: generated by make_wide.py from frontier_split1_fixed2.c (128-bit board masks, up to 10 files). */
/* frontier_split1_fixed2.c -- frontier_split1_fixed.c plus replacement at the table cap (FIX 2 in solve()).
 * Based on: frontier_split1_fixed.c -- frontier_split1.c with the memo-table stale-pointer bug fixed.
 * Build: cc -O2 -o frontier_split1_fixed frontier_split1_fixed.c
 * Run:   ./frontier_split1_fixed --cylinder --width 6 --min 9 --max 9 --nw 4 --nb 5 --only-setting 2 --chunk 0 4
 *
 * Changes against frontier_split1.c (see BUGFIX_frontier_split1.md):
 *  (1) solve(): the slot pointer `e` was obtained BEFORE the recursive gen() calls and used after
 *      them.  A nested solve() may call tab_grow(), which free()s the old table, so `e` dangled and
 *      the store wrote into freed memory (SIGSEGV once the freed block was returned to the OS, i.e.
 *      for tables of several GB; silently lost entry otherwise).  The slot is now looked up again
 *      after the recursion, immediately before the store.
 *  (2) enum_roots(): iw[8]/ib[8] overflowed for a side with 9 pawns (--max 10, split 1+9 / 9+1);
 *      they are now sized 16.
 *  (3) enum_roots(): white combinations outside the chunk skip the black loop (pure speed-up, the
 *      root set and its order are unchanged).
 */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define KMAX 64
#define FULL UINT64_MAX
typedef unsigned __int128 M;   /* board mask: square = (rank-1)*16 + file */
static inline int ctz128(M m) { uint64_t lo = (uint64_t)m; return lo ? __builtin_ctzll(lo) : 64 + __builtin_ctzll((uint64_t)(m >> 64)); }

static int W;          /* board width, 1..8; width 9 has no <=8-pawn ring */
static int WRAP;       /* cylindrical file adjacency */
static int RACE;       /* 0 count, 1 mover, 2 opponent */
static int EPON;       /* e.p. allowed */
static int AWARE;      /* e.p.-capturable pawn does not count as passed */

static inline int SQ(int f, int r) { return (r - 1) * 16 + f; }
static inline M B(int f, int r) { return ((M)1) << SQ(f, r); }
static inline int FILEOF(int s) { return s & 15; }
static inline int RANKOF(int s) { return (s >> 4) + 1; }

static M frontW[128], frontB[128];
static M filemask[16];

/* chunking: the white combinations are enumerated in a fixed order; chunk I of N
 * keeps only the white combinations whose index lies in [I/N, (I+1)/N).  The
 * chunks partition the root set exactly, so running them all is identical to
 * one unchunked run. */
static int CHUNK_I = 0, CHUNK_N = 1;
static long PROGRESS = 0;   /* print a progress line every PROGRESS roots (0 = off) */

static uint64_t comb(int n, int k) {
    uint64_t r = 1;
    for (int i = 0; i < k; i++) r = r * (uint64_t)(n - i) / (uint64_t)(i + 1);
    return r;
}

static void init_masks(void) {
    for (int f = 0; f < W; f++) {
        filemask[f] = 0;
        for (int r = 1; r <= 8; r++) filemask[f] |= B(f, r);
    }
    for (int f = 0; f < W; f++)
        for (int r = 1; r <= 8; r++) {
            M mw = 0, mb = 0;
            for (int d = -1; d <= 1; d++) {
                int g = f + d;
                if (WRAP) g = (g + W) % W;
                else if (g < 0 || g >= W) continue;
                for (int s = 1; s <= 8; s++) {
                    if (s > r) mw |= B(g, s);
                    if (s < r) mb |= B(g, s);
                }
            }
            frontW[SQ(f, r)] = mw;
            frontB[SQ(f, r)] = mb;
        }
}

static int ep_capturable(M ep3, M ep6, int white, int s) {
    return white ? (RANKOF(s) == 4 && (ep3 & B(FILEOF(s), 3)))
                 : (RANKOF(s) == 5 && (ep6 & B(FILEOF(s), 6)));
}

static int passedW(M wm, M bm, M ep3, M ep6) {
    for (M m = wm; m; m &= m - 1) {
        int s = ctz128(m);
        if (!(bm & frontW[s])) {
            if (AWARE && ep_capturable(ep3, ep6, 1, s)) continue;
            return 1;
        }
    }
    return 0;
}
static int passedB(M wm, M bm, M ep3, M ep6) {
    for (M m = bm; m; m &= m - 1) {
        int s = ctz128(m);
        if (!(wm & frontB[s])) {
            if (AWARE && ep_capturable(ep3, ep6, 0, s)) continue;
            return 1;
        }
    }
    return 0;
}

static int dist(M wm, M bm, M ep3, M ep6, int white) {
    int best = 1000000;
    M occ = wm | bm;
    if (white) {
        for (M m = wm; m; m &= m - 1) {
            int s = ctz128(m), f = FILEOF(s), r = RANKOF(s);
            if (bm & frontW[s]) continue;
            if (AWARE && ep_capturable(ep3, ep6, 1, s)) continue;
            int front = 1;
            for (int q = r + 1; q <= 8; q++) if (occ & B(f, q)) front = 0;
            if (!front) continue;
            int d = 8 - r - (r == 2);
            if (d < best) best = d;
        }
    } else {
        for (M m = bm; m; m &= m - 1) {
            int s = ctz128(m), f = FILEOF(s), r = RANKOF(s);
            if (wm & frontB[s]) continue;
            if (AWARE && ep_capturable(ep3, ep6, 0, s)) continue;
            int front = 1;
            for (int q = 1; q < r; q++) if (occ & B(f, q)) front = 0;
            if (!front) continue;
            int d = r - 1 - (r == 7);
            if (d < best) best = d;
        }
    }
    return best;
}

/* ------------------------------------------------------------------ memo */
typedef struct { uint64_t WL, WR; } Value;
typedef struct { M wm, bm, ep3, ep6; Value val; uint8_t used; } Entry;
static Entry *tab;
static uint64_t tcap, tcount;
static uint64_t TAB_CAP = 0;      /* 0 = grow without bound; else cap the table size */
static Entry *tab_dummy = NULL;   /* scratch slot used when the table is full */

static inline uint64_t mix(uint64_t x);
static inline uint64_t mixM(M x) { return mix((uint64_t)x ^ mix((uint64_t)(x >> 64) + 0x1234567ull)); }
static inline uint64_t mix(uint64_t x) {
    x += 0x9E3779B97F4A7C15ull;
    x = (x ^ (x >> 30)) * 0xBF58476D1CE4E5B9ull;
    x = (x ^ (x >> 27)) * 0x94D049BB133111EBull;
    return x ^ (x >> 31);
}
static void tab_init(uint64_t cap) {
    free(tab);
    tcap = cap; tcount = 0;
    if (TAB_CAP && tcap > TAB_CAP) tcap = TAB_CAP;
    tab = calloc(tcap, sizeof(Entry));
    if (!tab) { fprintf(stderr, "out of memory\n"); exit(1); }
    if (!tab_dummy) {
        tab_dummy = calloc(1, sizeof(Entry));
        if (!tab_dummy) { fprintf(stderr, "out of memory\n"); exit(1); }
    }
}
static Entry *tab_find(M wm, M bm, M ep3, M ep6) {
    uint64_t h = mix(mixM(wm) ^ mix(mixM(bm)) ^ mix(mixM(ep3)) ^ mix(mixM(ep6))) & (tcap - 1);
    uint64_t start = h;
    while (tab[h].used && !(tab[h].wm == wm && tab[h].bm == bm &&
                            tab[h].ep3 == ep3 && tab[h].ep6 == ep6)) {
        h = (h + 1) & (tcap - 1);
        if (h == start) return tab_dummy;   /* table full: no room, treat as a miss */
    }
    return &tab[h];
}
static void tab_grow(void) {
    if (TAB_CAP && tcap >= TAB_CAP) return;   /* capped: stay at the cap */
    Entry *old = tab; uint64_t oc = tcap;
    tab = calloc(oc * 2, sizeof(Entry)); tcap = oc * 2;
    if (!tab) { fprintf(stderr, "out of memory\n"); exit(1); }
    for (uint64_t i = 0; i < oc; i++) if (old[i].used)
        *tab_find(old[i].wm, old[i].bm, old[i].ep3, old[i].ep6) = old[i];
    free(old);
}

/* ------------------------------------------------------------------ search */
static Value solve(M wm, M bm, M ep3, M ep6);

/* Occupied-file connected component containing g; ponytail: O(W^2), W <= 8. */
static uint32_t component_files(M occ, int g) {
    uint32_t comp = 1u << g;
    int changed;
    do {
        changed = 0;
        for (int f = 0; f < W; f++) if (comp & (1u << f))
            for (int d = -1; d <= 1; d += 2) {
                int q = f + d;
                if (WRAP) q = (q + W) % W;
                else if (q < 0 || q >= W) continue;
                uint32_t bit = 1u << q;
                if (!(comp & bit) && (occ & filemask[q])) { comp |= bit; changed = 1; }
            }
    } while (changed);
    return comp;
}

static M clear_component_ep(M ep, uint32_t files) {
    for (int f = 0; f < W; f++) if (files & (1u << f)) ep &= ~filemask[f];
    return ep;
}

static uint64_t child_mask(M wm, M bm, M ep3, M ep6, int white) {
    int pw = passedW(wm, bm, ep3, ep6), pb = passedB(wm, bm, ep3, ep6);
    if (pw && pb) {
        int winner_white;
        if (RACE == 1) winner_white = white;
        else if (RACE == 2) winner_white = !white;
        else {
            int dm = dist(wm, bm, ep3, ep6, white), dop = dist(wm, bm, ep3, ep6, !white);
            winner_white = (dop <= dm) ? !white : white;
        }
        return (winner_white == white) ? FULL : 0;
    }
    if (pw) return white ? FULL : 0;
    if (pb) return white ? 0 : FULL;
    Value v = solve(wm, bm, ep3, ep6);
    uint64_t opp_wins = white ? v.WR : v.WL;
    return (~opp_wins) & FULL;
}

static int has_ep_capturer(M pawns, int f, int r) {
    for (int d = -1; d <= 1; d += 2) {
        int g = f + d;
        if (WRAP) g = (g + W) % W;
        else if (g < 0 || g >= W) continue;
        if (pawns & B(g, r)) return 1;
    }
    return 0;
}

static uint64_t gen(M wm, M bm, M ep3, M ep6, int white) {
    uint64_t acc = 0;
    M occ = wm | bm;
    M mine = white ? wm : bm, theirs = white ? bm : wm;
    int d = white ? 1 : -1, start = white ? 2 : 7;
    for (M m = mine; m && acc != FULL; m &= m - 1) {
        int s = ctz128(m), f = FILEOF(s), r = RANKOF(s);
        int r1 = r + d;
        if (r1 < 1 || r1 > 8) continue;
        /* VARIANT R: any move clears every e.p. right on the board (real-chess expiry) */
        M base_ep3 = 0, base_ep6 = 0;
        (void)component_files; (void)clear_component_ep;
        M rest = mine & ~B(f, r);
        if (!(occ & B(f, r1))) {
            M nm = rest | B(f, r1);
            acc |= white ? child_mask(nm, theirs, base_ep3, base_ep6, 1)
                         : child_mask(theirs, nm, base_ep3, base_ep6, 0);
            int r2 = r + 2 * d;
            if (r == start && !(occ & B(f, r2))) {
                M nm2 = rest | B(f, r2), cep3 = base_ep3, cep6 = base_ep6;
                if (EPON && has_ep_capturer(theirs, f, r2)) {
                    if (white) cep3 |= B(f, r1); else cep6 |= B(f, r1);
                }
                acc |= white ? child_mask(nm2, theirs, cep3, cep6, 1)
                             : child_mask(theirs, nm2, cep3, cep6, 0);
            }
        }
        for (int side = -1; side <= 1; side += 2) {
            int g = f + side;
            if (WRAP) g = (g + W) % W;
            else if (g < 0 || g >= W) continue;
            if (theirs & B(g, r1)) {
                M nm = rest | B(g, r1), nt = theirs & ~B(g, r1);
                acc |= white ? child_mask(nm, nt, base_ep3, base_ep6, 1)
                             : child_mask(nt, nm, base_ep3, base_ep6, 0);
            } else if ((white && (ep6 & B(g, r1))) || (!white && (ep3 & B(g, r1)))) {
                int victim_r = white ? r1 - 1 : r1 + 1;
                M nm = rest | B(g, r1), nt = theirs & ~B(g, victim_r);
                acc |= white ? child_mask(nm, nt, base_ep3, base_ep6, 1)
                             : child_mask(nt, nm, base_ep3, base_ep6, 0);
            }
        }
    }
    return acc;
}

static Value solve(M wm, M bm, M ep3, M ep6) {
    Entry *e = tab_find(wm, bm, ep3, ep6);
    if (e->used) return e->val;
    uint64_t AL = gen(wm, bm, ep3, ep6, 1), AR = gen(wm, bm, ep3, ep6, 0);
    uint64_t WL = 0, WR = 0;
    int lose_L_seen = 0, lose_R_seen = 0;
    for (int k = 0; k < KMAX; k++) {
        int wl = ((AL >> k) & 1) || lose_R_seen;
        int wr = ((AR >> k) & 1) || lose_L_seen;
        if (wl) WL |= UINT64_C(1) << k;
        if (wr) WR |= UINT64_C(1) << k;
        if (!wr) lose_R_seen = 1;
        if (!wl) lose_L_seen = 1;
    }
    Value v = {WL, WR};
    if ((tcount + 1) * 2 > tcap) tab_grow();
    /* FIX: `e` (found before the recursion) may point into a table that a nested solve() has
     * since grown and free()d, or into a slot that a nested solve() has since filled.  Look the
     * slot up again now.  (A state is never its own descendant, so it cannot be present yet.) */
    e = tab_find(wm, bm, ep3, ep6);
    if (e == tab_dummy || e->used) return v;   /* cache is full / already stored: value is the same */
    if (tcount + 1 >= (tcap / 16) * 15) {
        /* FIX 2: the table is at its cap and 15/16 full.  Freezing it (the old behaviour) turns the memoised
         * search into a tree search, which can take hours.  Instead overwrite the entry in this key's home
         * slot, as a transposition table does.  Probe chains stay intact (no slot becomes empty), the evicted
         * state is simply recomputed if needed, and solve() is a pure function, so no value can change. */
        uint64_t h = mix(mixM(wm) ^ mix(mixM(bm)) ^ mix(mixM(ep3)) ^ mix(mixM(ep6))) & (tcap - 1);
        Entry *r = &tab[h];
        r->wm = wm; r->bm = bm; r->ep3 = ep3; r->ep6 = ep6; r->val = v; r->used = 1;
        return v;
    }
    e->wm = wm; e->bm = bm; e->ep3 = ep3; e->ep6 = ep6; e->val = v; e->used = 1; tcount++;
    return v;
}

/* ------------------------------------------------------------------ roots */
typedef struct { M wm, bm; int n; } Root;
static Root *roots; static int nroots, rcap;

static M transform(M m, int shift, int reflect) {
    M out = 0;
    for (; m; m &= m - 1) {
        int s = ctz128(m), f = FILEOF(s), r = RANKOF(s);
        if (reflect) f = W - 1 - f;
        f = (f + shift) % W;
        out |= B(f, r);
    }
    return out;
}

static int canonical_root(M wm, M bm) {
    M bestw = wm, bestb = bm;
    int variants = WRAP ? 2 * W : 1;
    for (int v = 0; v < variants; v++) {
        int refl = WRAP ? v / W : 1;
        int shift = WRAP ? v % W : 0;
        M tw = transform(wm, shift, refl), tb = transform(bm, shift, refl);
        if (tw < bestw || (tw == bestw && tb < bestb)) { bestw = tw; bestb = tb; }
    }
    return wm == bestw && bm == bestb;
}

static void add_root(M wm, M bm, int n) {
    if (!canonical_root(wm, bm)) return;
    if (nroots == rcap) {
        rcap = rcap ? rcap * 2 : 1024;
        roots = realloc(roots, (size_t)rcap * sizeof(Root));
        if (!roots) { fprintf(stderr, "root allocation failed\n"); exit(1); }
    }
    roots[nroots++] = (Root){wm, bm, n};
}

/* Enumerate no-passer roots. W-rank-7 and B-rank-2 pawns are necessarily
   passed because roots have no pawns on ranks 8 and 1, so omitting them is exact. */
static void enum_roots(int nw, int nb, int n) {
    int wc[64], bc[64], nwc = 0, nbc = 0;
    for (int f = 0; f < W; f++) {
        for (int r = 2; r <= 6; r++) wc[nwc++] = SQ(f, r);
        for (int r = 3; r <= 7; r++) bc[nbc++] = SQ(f, r);
    }
    if (nw > nwc || nb > nbc) return;
    int iw[16], ib[16];   /* nw, nb <= 9 (maxp <= 10); [8] overflowed for 9 pawns */
    for (int i = 0; i < nw; i++) iw[i] = i;
    uint64_t wseq = 0;   /* index of the current white combination */
    while (1) {
        M wm = 0;
        for (int i = 0; i < nw; i++) wm |= B(wc[iw[i]] % 16, (wc[iw[i]] / 16) + 1);
        int in_chunk = 1;
        if (CHUNK_N > 1) {
            uint64_t total = comb(nwc, nw);
            uint64_t lo = (uint64_t)CHUNK_I * total / CHUNK_N;
            uint64_t hi = (uint64_t)(CHUNK_I + 1) * total / CHUNK_N;
            in_chunk = (wseq >= lo && wseq < hi);
        }
        for (int i = 0; i < nb; i++) ib[i] = i;
        while (in_chunk) {
            M bm = 0;
            for (int i = 0; i < nb; i++) bm |= B(bc[ib[i]] % 16, (bc[ib[i]] / 16) + 1);
            if (in_chunk && !(wm & bm)) {
                M occ = wm | bm;
                int edge_ok = 1;
                for (int f = 0; f < W; f++)
                    if ((WRAP || f == 0 || f == W - 1) && !(occ & filemask[f])) edge_ok = 0;
                if (edge_ok && !passedW(wm, bm, 0, 0) && !passedB(wm, bm, 0, 0)) add_root(wm, bm, n);
            }
            int i = nb - 1;
            while (i >= 0 && ib[i] == nbc - nb + i) i--;
            if (i < 0) break;
            ib[i]++;
            for (int j = i + 1; j < nb; j++) ib[j] = ib[j - 1] + 1;
        }
        wseq++;
        int i = nw - 1;
        while (i >= 0 && iw[i] == nwc - nw + i) i--;
        if (i < 0) break;
        iw[i]++;
        for (int j = i + 1; j < nw; j++) iw[j] = iw[j - 1] + 1;
    }
}

static void pos_str(char *out, M wm, M bm) {
    char *p = out;
    p += sprintf(p, "W:");
    for (int f = 0; f < W; f++) for (int r = 1; r <= 8; r++) if (wm & B(f, r)) p += sprintf(p, " %c%d", 'a' + f, r);
    p += sprintf(p, " / B:");
    for (int f = 0; f < W; f++) for (int r = 1; r <= 8; r++) if (bm & B(f, r)) p += sprintf(p, " %c%d", 'a' + f, r);
}

static int choose_samples(int per_n, int minp, int maxp, unsigned char *selected) {
    if (per_n <= 0) { memset(selected, 1, (size_t)nroots); return nroots; }
    int count_selected = 0;
    for (int n = minp; n <= maxp; n++) {
        int count = 0;
        for (int i = 0; i < nroots; i++) if (roots[i].n == n) count++;
        int take = count < per_n ? count : per_n, ordinal = 0;
        for (int i = 0; i < nroots; i++) if (roots[i].n == n) {
            if ((int64_t)ordinal * take / count != (int64_t)(ordinal + 1) * take / count) {
                selected[i] = 1; count_selected++;
            }
            ordinal++;
        }
    }
    return count_selected;
}

int main(int argc, char **argv) {
    int minp = 2, maxp = 6, wmin = 1, wmax = 4, pilot = 0;
    int split_nw = -1, split_nb = -1, width = -1;
    int only_setting = -1;   /* -1 = all nine settings; else 0..8 (see s_race below) */
    for (int i = 1; i < argc; i++)
        if (!strcmp(argv[i], "--test") && i + 1 < argc) { fprintf(stderr, "--test not supported in split mode\n"); return 1; }
        else if (!strcmp(argv[i], "--eval") && i + 1 < argc) { fprintf(stderr, "--eval not supported in split mode\n"); return 1; }
    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "--max") && i + 1 < argc) maxp = atoi(argv[++i]);
        else if (!strcmp(argv[i], "--min") && i + 1 < argc) minp = atoi(argv[++i]);
        else if (!strcmp(argv[i], "--width-min") && i + 1 < argc) wmin = atoi(argv[++i]);
        else if (!strcmp(argv[i], "--width-max") && i + 1 < argc) wmax = atoi(argv[++i]);
        else if (!strcmp(argv[i], "--width") && i + 1 < argc) width = atoi(argv[++i]);
        else if (!strcmp(argv[i], "--nw") && i + 1 < argc) split_nw = atoi(argv[++i]);
        else if (!strcmp(argv[i], "--nb") && i + 1 < argc) split_nb = atoi(argv[++i]);
        else if (!strcmp(argv[i], "--pilot") && i + 1 < argc) pilot = atoi(argv[++i]);
        else if (!strcmp(argv[i], "--only-setting") && i + 1 < argc) only_setting = atoi(argv[++i]);
        else if (!strcmp(argv[i], "--chunk") && i + 2 < argc) { CHUNK_I = atoi(argv[++i]); CHUNK_N = atoi(argv[++i]); }
        else if (!strcmp(argv[i], "--max-entries") && i + 1 < argc) TAB_CAP = (uint64_t)atoll(argv[++i]);
        else if (!strcmp(argv[i], "--progress") && i + 1 < argc) PROGRESS = atol(argv[++i]);
        else if (!strcmp(argv[i], "--cylinder")) WRAP = 1;
        else if (!strcmp(argv[i], "--flat")) WRAP = 0;
    }
    if (width >= 0) { wmin = wmax = width; }
    if (wmin < 1 || wmax < wmin || wmax > 10 || minp < 2 || maxp < minp || maxp > 10 || pilot < 0) {
        fprintf(stderr, "invalid range (width 1..10, pawns 2..10, pilot >= 0)\n"); return 2;
    }
    if (split_nw < 1 || split_nb < 1 || split_nw + split_nb != maxp) {
        fprintf(stderr, "must specify --nw and --nb such that nw+nb=maxp (and maxp=minp)\n"); return 2;
    }
    /* settings: race x (ep off | ep on textbook | ep on aware) */
    const char *rname[3] = {"count", "mover", "opponent"};
    int nset = 9, s_race[9], s_ep[9], s_aware[9];
    for (int r = 0, k = 0; r < 3; r++) {
        s_race[k] = r; s_ep[k] = 1; s_aware[k++] = 0;
        s_race[k] = r; s_ep[k] = 0; s_aware[k++] = 0;
        s_race[k] = r; s_ep[k] = 1; s_aware[k++] = 1;
    }
    /* setting indices to evaluate and print */
    int sidx[9], nsidx = 0;
    if (only_setting >= 0 && only_setting < 9) sidx[nsidx++] = only_setting;
    else for (int k = 0; k < 9; k++) sidx[nsidx++] = k;
    printf("#position\twidth\tnpawns");
    for (int j = 0; j < nsidx; j++) { int k = sidx[j];
        printf("\t%s/%s%s", rname[s_race[k]], s_ep[k] ? "epon" : "epoff", s_aware[k] ? "/aware" : ""); }
    printf("\n");
    char buf[1024];
    for (int w = wmin; w <= wmax; w++) {
        W = w; nroots = 0;
        init_masks();
        clock_t enum0 = clock();
        enum_roots(split_nw, split_nb, split_nw + split_nb);
        double enum_secs = (double)(clock() - enum0) / CLOCKS_PER_SEC;
        fprintf(stderr, "W=%d flat split=%d+%d roots_ready=%d enumeration_cpu=%.3fs\n", W, split_nw, split_nb, nroots, enum_secs);
        unsigned char *selected = calloc((size_t)(nroots ? nroots : 1), 1);
        int nselected = choose_samples(pilot, minp, maxp, selected);
        char *res = calloc((size_t)(nroots ? nroots : 1) * nset, 1);
        int *nim = calloc((size_t)(nroots ? nroots : 1) * nset, sizeof(int));
        if (!selected || !res || !nim) { fprintf(stderr, "result allocation failed\n"); return 1; }
        for (int j = 0; j < nsidx; j++) {
            int k = sidx[j];
            RACE = s_race[k]; EPON = s_ep[k]; AWARE = s_aware[k];
            clock_t c0 = clock(); tab_init(1u << 18);
            for (int i = 0; i < nroots; i++) if (selected[i]) {
                Value v = solve(roots[i].wm, roots[i].bm, 0, 0);
                uint64_t WL = v.WL, WR = v.WR;
                res[i * nset + k] = (WL & 1) && (WR & 1) ? 'N' : (WL & 1) ? 'L' : (WR & 1) ? 'R' : 'P';
                int nk = -1;
                for (int q = 0; q < KMAX; q++) if (!((WL >> q) & 1) && !((WR >> q) & 1)) { nk = q; break; }
                nim[i * nset + k] = nk;
                if (PROGRESS > 0 && ((i + 1) % PROGRESS == 0))
                    fprintf(stderr, "  progress: setting=%d root %d/%d states=%llu\n",
                            k, i + 1, nroots, (unsigned long long)tcount);
            }
            double secs = (double)(clock() - c0) / CLOCKS_PER_SEC;
            double total_est = nroots;
            double projected = nselected ? secs * total_est / nselected : 0;
            fprintf(stderr, "W=%d flat setting=%d (%s ep=%d aware=%d): roots=%d sampled=%d states=%llu cpu=%.3fs projected=%.3fs\n",
                    W, k, rname[RACE], EPON, AWARE, nroots, nselected,
                    (unsigned long long)tcount, secs, projected);
        }
        for (int i = 0; i < nroots; i++) if (selected[i]) {
            pos_str(buf, roots[i].wm, roots[i].bm);
            printf("%s\t%d\t%d", buf, W, roots[i].n);
            for (int j = 0; j < nsidx; j++) { int k = sidx[j];
                printf("\t%c,%d", res[i * nset + k], nim[i * nset + k]); }
            printf("\n");
        }
        free(selected); free(res); free(nim);
    }
    return 0;
}